export async function openSupport({rpc,element:E,button:B,busy,toast,platform=false}){
 const call=(action,payload={})=>rpc('support_action',{action,payload:{...payload,platform}});const d=E('dialog',undefined,'support-dialog');d.append(E('h2',platform?'طلبات الدعم الفني':'الدعم الفني'),B('إغلاق',()=>{d.close();d.remove()}));const body=E('div');d.append(body);document.body.append(d);d.showModal();let selected=null,after=0,epoch=0;const date=v=>new Date(v).toLocaleString('ar-SA');
 async function list(){selected=null;const n=++epoch,rows=await call('list');if(!d.open||n!==epoch)return;body.replaceChildren(B('تحديث الطلبات',()=>busy(null,list),'secondary'));if(!platform){const form=E('form'),subject=E('input'),text=E('textarea'),send=E('button','إرسال طلب دعم','primary');subject.required=text.required=true;subject.minLength=3;subject.maxLength=200;text.maxLength=5000;subject.placeholder='عنوان الطلب';text.placeholder='اشرح المشكلة…';subject.setAttribute('aria-label','عنوان طلب الدعم');text.setAttribute('aria-label','تفاصيل طلب الدعم');form.append(subject,text,send);form.onsubmit=e=>{e.preventDefault();busy(send,async()=>{const ticket=await call('create',{subject:subject.value,body:text.value});await thread(ticket)})};body.append(form)}for(const t of rows){const b=B('',()=>busy(null,()=>thread(t)),'support-ticket');b.append(E('strong',t.subject),E('small',(platform?t.family_name+' · '+t.family_code+' · ':'')+(t.status==='closed'?'مغلق':'مفتوح')+' · '+date(t.updated_at)),E('span',t.last_from_platform?'آخر رد من إدارة المنصة':'آخر رسالة من مدير العائلة'));body.append(b)}if(!rows.length)body.append(E('p','لا توجد طلبات دعم.'))}
 async function thread(t){const n=++epoch;selected=t;after=0;body.replaceChildren(B('العودة للطلبات',()=>busy(null,list)),E('h3',t.subject));const messages=E('div',undefined,'support-messages'),more=B('تحميل رسائل أخرى',()=>busy(more,read),'secondary');body.append(messages,more);async function read(){const rows=await call('messages',{ticket:t.id,after});if(!d.open||n!==epoch)return;for(const m of rows){const row=E('article',undefined,'support-message'+(m.from_platform?' from-platform':''));row.append(E('strong',m.from_platform?'إدارة المنصة':'مدير العائلة'),E('p',m.body),E('small',date(m.created_at)));messages.append(row)}after=rows.at(-1)?.id||after;more.hidden=rows.length<100}const f=E('form'),text=E('textarea'),send=E('button','إرسال الرد','primary');text.required=true;text.maxLength=5000;text.placeholder='اكتب ردك…';text.setAttribute('aria-label','الرد على طلب الدعم');f.append(text,send);f.onsubmit=e=>{e.preventDefault();busy(send,async()=>{await call('reply',{ticket:t.id,body:text.value});text.value='';await read()})};body.append(f,B('إغلاق الطلب',()=>busy(null,async()=>{await call('close',{ticket:t.id});toast('أُغلق الطلب.');await list()}),'secondary'));await read();const timer=setInterval(()=>{if(!d.open||n!==epoch)return clearInterval(timer);read().catch(()=>{})},10000);timer.unref?.();d.addEventListener('close',()=>clearInterval(timer),{once:true})}
 d.addEventListener('close',()=>{epoch++});try{await list()}catch(e){toast(e.message);d.close();d.remove()}
}
